1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, materializes the
5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
6	 * to result.json at RESULT_PATH.
7	 *
8	 * Formal ABI env vars (from ExecutorInput):
9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
11	 *   BRIEFING_PATH, RESULT_PATH
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_KEY_PATH, GITHUB_TOKEN
14	 *
15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
17	 *   TASK_BRANCH        — management repo feature branch for git commits
18	 *   GIT_AUTHOR_EMAIL   — for commit identity
19	 *   GIT_AUTHOR_NAME    — for commit identity
20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
25	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
26	 */
27	
28	import { spawn, execSync } from "node:child_process";
29	import {
30	  mkdirSync,
31	  appendFileSync,
32	  readFileSync,
33	  writeFileSync,
34	  existsSync,
35	  readdirSync,
36	  rmSync,
37	  copyFileSync,
38	  lstatSync,
39	} from "node:fs";
40	import { join, dirname } from "node:path";
41	import { homedir } from "node:os";
42	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
43	import type { ExecutorResult } from "@workflow/runtime-abi";
44	import { isValidResult } from "@workflow/runtime-abi";
45	import { extractTokenUsage } from "./token-usage.js";
46	
47	// ── Helpers ───────────────────────────────────────────────────────────────────
48	
49	function requireEnv(name: string): string {
50	  const val = process.env[name];
51	  if (!val) throw new Error(`Required env var ${name} is not set`);
52	  return val;
53	}
54	
55	function emit(event: Record<string, unknown>): void {
56	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
57	}
58	
59	function buildGitEnv(sshKeyPath: string | undefined): NodeJS.ProcessEnv {
60	  if (!sshKeyPath) return process.env;
61	  return {
62	    ...process.env,
63	    GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new`,
64	  };
65	}
66	
67	/**
68	 * Materialize the implementation repo at taskRepoPath:
69	 *   - If path exists and origin matches URL: fetch + checkout + pull
70	 *   - Otherwise: clone fresh
71	 */
72	function materializeRepo(
73	  taskRepoUrl: string,
74	  taskRepoBranch: string,
75	  taskRepoPath: string,
76	  sshKeyPath: string | undefined,
77	): void {
78	  const env = buildGitEnv(sshKeyPath);
79	  const opts = { env, stdio: "pipe" as const };
80	
81	  if (existsSync(join(taskRepoPath, ".git"))) {
82	    let originUrl = "";
83	    try {
84	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
85	        ...opts, encoding: "utf-8",
86	      }).trim();
87	    } catch { /* no remote — fall through to clone */ }
88	
89	    if (originUrl === taskRepoUrl) {
90	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
91	      execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
92	      try {
93	        execSync(
94	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
95	          opts,
96	        );
97	      } catch {
98	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
99	      }
100	      return;
101	    }
102	  }
103	
104	  // Clone fresh.
105	  mkdirSync(dirname(taskRepoPath), { recursive: true });
106	  if (existsSync(taskRepoPath)) {
107	    rmSync(taskRepoPath, { recursive: true, force: true });
108	  }
109	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
110	  execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
111	}
112	
113	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
114	  { file: "yarn.lock",        tool: "yarn"    },
115	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
116	  { file: "bun.lockb",        tool: "bun"     },
117	  { file: "go.mod",           tool: "go"      },
118	  { file: "requirements.txt", tool: "python3" },
119	  { file: "pyproject.toml",   tool: "python3" },
120	  { file: "Cargo.toml",       tool: "cargo"   },
121	];
122	
123	function checkRequiredTools(taskRepoPath: string): string[] {
124	  const missing: string[] = [];
125	  const checked = new Set<string>();
126	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
127	    if (checked.has(tool)) continue;
128	    if (!existsSync(join(taskRepoPath, file))) continue;
129	    checked.add(tool);
130	    try {
131	      execSync(`which ${tool}`, { stdio: "pipe" });
132	    } catch {
133	      missing.push(tool);
134	    }
135	  }
136	  return missing;
137	}
138	
139	function copyWorkspaceClaude(workspaceRoot: string): void {
140	  const src = join(workspaceRoot, "CLAUDE.md");
141	  if (!existsSync(src)) return;
142	  const destDir = join(homedir(), ".claude");
143	  mkdirSync(destDir, { recursive: true });
144	  copyFileSync(src, join(destDir, "CLAUDE.md"));
145	}
146	
147	function copyDirRecursive(src: string, dest: string): void {
148	  mkdirSync(dest, { recursive: true });
149	  for (const entry of readdirSync(src)) {
150	    const srcPath = join(src, entry);
151	    const destPath = join(dest, entry);
152	    const stat = lstatSync(srcPath);
153	    if (stat.isDirectory()) {
154	      copyDirRecursive(srcPath, destPath);
155	    } else if (stat.isFile()) {
156	      copyFileSync(srcPath, destPath);
157	    }
158	  }
159	}
160	
161	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
162	  const globalSkillsDir = join(homedir(), ".claude", "skills");
163	  if (existsSync(globalSkillsDir)) {
164	    rmSync(globalSkillsDir, { recursive: true, force: true });
165	  }
166	  mkdirSync(globalSkillsDir, { recursive: true });
167	
168	  const copySkillsFrom = (sourceDir: string): void => {
169	    if (!existsSync(sourceDir)) return;
170	    let entries: string[];
171	    try { entries = readdirSync(sourceDir); } catch { return; }
172	    for (const entry of entries) {
173	      const srcPath = join(sourceDir, entry);
174	      try {
175	        const stat = lstatSync(srcPath);
176	        if (!stat.isDirectory()) continue;
177	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
178	      } catch (e) {
179	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
180	      }
181	    }
182	  };
183	
184	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
185	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
186	
187	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
188	  if (existsSync(wsSkillsDir)) {
189	    let entries: string[];
190	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
191	    for (const entry of entries) {
192	      if (entry === ".gitignore") continue;
193	      const srcPath = join(wsSkillsDir, entry);
194	      try {
195	        const stat = lstatSync(srcPath);
196	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
197	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
198	      } catch (e) {
199	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
200	      }
201	    }
202	  }
203	}
204	
205	function writeResult(resultPath: string, result: ExecutorResult): void {
206	  mkdirSync(dirname(resultPath), { recursive: true });
207	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
208	}
209	
210	function isMaxTurnsExit(stdout: string): boolean {
211	  for (const line of stdout.split("\n")) {
212	    const trimmed = line.trim();
213	    if (!trimmed.startsWith("{")) continue;
214	    try {
215	      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
216	      if (parsed.type === "result" && parsed.subtype === "error_max_turns") return true;
217	    } catch { /* skip non-JSON lines */ }
218	  }
219	  return false;
220	}
221	
222	// ── Main ──────────────────────────────────────────────────────────────────────
223	
224	async function main(): Promise<void> {
225	  // ── Read formal ABI env vars ────────────────────────────────────────────────
226	  let taskId: string;
227	  let featureId: string;
228	  let taskRepoUrl: string;
229	  let taskRepoBranch: string;
230	  let taskRepoPath: string;
231	  let briefingPath: string;
232	  let resultPath: string;
233	  let sshKeyPath: string | undefined;
234	  let githubToken: string;
235	
236	  try {
237	    taskId = requireEnv("TASK_ID");
238	    featureId = requireEnv("FEATURE_ID");
239	    taskRepoUrl = requireEnv("TASK_REPO_URL");
240	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
241	    taskRepoPath = requireEnv("TASK_REPO_PATH");
242	    briefingPath = requireEnv("BRIEFING_PATH");
243	    resultPath = requireEnv("RESULT_PATH");
244	    githubToken = process.env.GITHUB_TOKEN ?? "";
245	    sshKeyPath = process.env.SSH_KEY_PATH || undefined;
246	  } catch (e) {
247	    emit({ type: "executor_fatal", details: (e as Error).message });
248	    process.exit(1);
249	  }
250	
251	  const budgetTokensStr = process.env.BUDGET_TOKENS;
252	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
253	
254	  // Day-1 single-container extras.
255	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
256	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
257	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
258	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
259	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
260	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
261	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
262	  const mcpRagUrl = process.env.MCP_RAG_URL;
263	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
264	
265	  const runStartIso = new Date().toISOString();
266	
267	  // ── 1. Materialize implementation repo ─────────────────────────────────────
268	  try {
269	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
270	  } catch (e) {
271	    const details = `repo materialization failed: ${String(e)}`;
272	    emit({ type: "executor_fatal", task_id: taskId, details });
273	    writeResult(resultPath, {
274	      terminal_status: "failed",
275	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
276	    });
277	    process.exit(0);
278	  }
279	
280	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
281	  const missingTools = checkRequiredTools(taskRepoPath);
282	  if (missingTools.length > 0) {
283	    const details = `missing tools: ${missingTools.join(", ")}`;
284	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
285	    writeResult(resultPath, {
286	      terminal_status: "blocked",
287	      blocked_reason: "missing_tool",
288	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
289	    });
290	    process.exit(0);
291	  }
292	
293	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
294	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
295	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
296	
297	  // ── 4. Read briefing ────────────────────────────────────────────────────────
298	  let briefingContent: string;
299	  try {
300	    briefingContent = readFileSync(briefingPath, "utf-8");
301	  } catch (e) {
302	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
303	    writeResult(resultPath, {
304	      terminal_status: "failed",
305	      blocked_reason: `briefing_read_failed: ${String(e)}`,
306	    });
307	    process.exit(0);
308	  }
309	
310	  // Append hard-stop rule for missing tools.
311	  const effectiveBriefing =
312	    briefingContent +
313	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
314	
315	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
316	  const mcpArgs: string[] = [];
317	  if (mcpRagUrl || figmaToken) {
318	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
319	    if (mcpRagUrl) {
320	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
321	    }
322	    if (figmaToken) {
323	      mcpConfig.mcpServers["figma"] = {
324	        type: "stdio",
325	        command: "npx",
326	        args: ["-y", "@figma/mcp-server"],
327	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
328	      };
329	    }
330	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
331	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
332	    mcpArgs.push("--mcp-config", mcpConfigPath);
333	  }
334	
335	  // ── 6. Spawn claude ─────────────────────────────────────────────────────────
336	  const claudeEnv = {
337	    ...buildGitEnv(sshKeyPath),
338	    CLAUDE_AGENT_RUNTIME: "1",
339	    RESULT_PATH: resultPath,
340	    GITHUB_TOKEN: githubToken,
341	    ...(sshKeyPath ? { SSH_KEY_PATH: sshKeyPath } : {}),
342	  };
343	
344	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
345	
346	  const spawnResult = await new Promise<{
347	    stdout: string;
348	    status: number | null;
349	    signal: string | null;
350	    error?: Error;
351	  }>((resolve) => {
352	    const stdoutChunks: string[] = [];
353	
354	    const child = spawn(
355	      "claude",
356	      [
357	        "-p", effectiveBriefing,
358	        "--max-turns", String(maxTurns),
359	        "--output-format", "stream-json",
360	        "--verbose",
361	        "--dangerously-skip-permissions",
362	        ...mcpArgs,
363	      ],
364	      { cwd: taskRepoPath, env: claudeEnv },
365	    );
366	
367	    child.stdout.setEncoding("utf-8");
368	    child.stderr.setEncoding("utf-8");
369	
370	    let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
371	    let stdoutLineBuf = "";
372	    child.stdout.on("data", (chunk: string) => {
373	      stdoutChunks.push(chunk);
374	      process.stdout.write(chunk);
375	      if (resultWatchdog === null) {
376	        stdoutLineBuf += chunk;
377	        const lines = stdoutLineBuf.split("\n");
378	        stdoutLineBuf = lines.pop() ?? "";
379	        for (const line of lines) {
380	          if (line.includes('"type":"result"')) {
381	            resultWatchdog = setTimeout(() => {
382	              if (!child.killed) child.kill("SIGTERM");
383	            }, 30_000);
384	            break;
385	          }
386	        }
387	      }
388	    });
389	
390	    child.stderr.on("data", (chunk: string) => {
391	      process.stderr.write(chunk);
392	    });
393	
394	    child.on("error", (err: Error) => {
395	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
396	      resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
397	    });
398	
399	    child.on("exit", () => {
400	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
401	      setTimeout(() => {
402	        if (!child.stdout.destroyed) child.stdout.destroy();
403	        if (!child.stderr.destroyed) child.stderr.destroy();
404	      }, 0);
405	    });
406	
407	    child.on("close", (code: number | null, signal: string | null) => {
408	      resolve({ stdout: stdoutChunks.join(""), status: code, signal });
409	    });
410	  });
411	
412	  emit({
413	    type: "claude_exit",
414	    task_id: taskId,
415	    feature_id: featureId,
416	    exit_code: spawnResult.status,
417	    signal: spawnResult.signal ?? null,
418	  });
419	
420	  // ── 7. Token audit ──────────────────────────────────────────────────────────
421	  const tokenUsage = spawnResult.stdout
422	    ? extractTokenUsage(spawnResult.stdout)
423	    : undefined;
424	
425	  if (tokenUsage === undefined) {
426	    emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
427	  } else {
428	    emit({
429	      type: "budget_audit",
430	      task_id: taskId,
431	      feature_id: featureId,
432	      total_tokens: tokenUsage.input + tokenUsage.output,
433	      max_tokens: budgetTokens,
434	    });
435	  }
436	
437	  // ── 8. Check for result.json written by Claude ──────────────────────────────
438	  if (existsSync(resultPath)) {
439	    let raw: unknown;
440	    try {
441	      raw = JSON.parse(readFileSync(resultPath, "utf-8"));
442	    } catch {
443	      raw = null;
444	    }
445	    if (isValidResult(raw)) {
446	      // Claude wrote a valid result — augment with token_usage if available.
447	      const claudeResult = raw as ExecutorResult;
448	      if (tokenUsage !== undefined && !claudeResult.token_usage) {
449	        claudeResult.token_usage = tokenUsage;
450	      }
451	
452	      // Budget exceeded check.
453	      if (
454	        budgetTokens !== undefined &&
455	        tokenUsage !== undefined &&
456	        tokenUsage.input + tokenUsage.output > budgetTokens
457	      ) {
458	        writeResult(resultPath, {
459	          terminal_status: "blocked",
460	          blocked_reason: "budget_exceeded",
461	          token_usage: tokenUsage,
462	        });
463	      } else {
464	        writeResult(resultPath, claudeResult);
465	      }
466	
467	      // Flush log (best-effort).
468	      if (logSinkEnabled && workspaceRoot && taskBranch) {
469	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
470	      }
471	      process.exit(0);
472	    }
473	  }
474	
475	  // ── 9. Claude did not write result.json — determine from task YAML ──────────
476	  // Day-1 fallback: if Claude didn't write result.json, read the task YAML.
477	  if (workspaceRoot) {
478	    let taskStatus = "in_progress";
479	    let blockedReason: string | undefined;
480	    let blockedSuggestion: string | undefined;
481	
482	    try {
483	      const yamlPath = join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
484	      const taskData = parseYaml(readFileSync(yamlPath, "utf-8")) as {
485	        status: string;
486	        blocked_reason?: string;
487	        blocked_suggestion?: string;
488	      };
489	      taskStatus = taskData.status;
490	      blockedReason = taskData.blocked_reason;
491	      blockedSuggestion = taskData.blocked_suggestion;
492	    } catch { /* use in_progress */ }
493	
494	    let result: ExecutorResult;
495	    if (taskStatus === "in_review") {
496	      result = { terminal_status: "in_review", ...(tokenUsage ? { token_usage: tokenUsage } : {}) };
497	    } else if (taskStatus === "blocked") {
498	      result = {
499	        terminal_status: "blocked",
500	        blocked_reason: blockedReason ?? "unknown",
501	        ...(blockedSuggestion ? { blocked_suggestion: blockedSuggestion } : {}),
502	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
503	      };
504	    } else if (!spawnResult.error && isMaxTurnsExit(spawnResult.stdout)) {
505	      result = {
506	        terminal_status: "blocked",
507	        blocked_reason: "max_turns_exceeded",
508	        blocked_suggestion: "Increase max_iterations in agent.yaml or break the task into smaller sub-tasks.",
509	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
510	      };
511	    } else {
512	      // task still in_progress — claude exited without completing
513	      const note = spawnResult.error
514	        ? `process error: ${spawnResult.error.message}`
515	        : `task still in_progress after claude exit (code ${spawnResult.status ?? "null"})`;
516	      result = {
517	        terminal_status: "failed",
518	        blocked_reason: `runtime_error: ${note}`,
519	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
520	      };
521	    }
522	
523	    if (
524	      budgetTokens !== undefined &&
525	      tokenUsage !== undefined &&
526	      tokenUsage.input + tokenUsage.output > budgetTokens &&
527	      result.terminal_status !== "failed"
528	    ) {
529	      result = {
530	        terminal_status: "blocked",
531	        blocked_reason: "budget_exceeded",
532	        token_usage: tokenUsage,
533	      };
534	    }
535	
536	    writeResult(resultPath, result);
537	
538	    if (logSinkEnabled && taskBranch) {
539	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, result.terminal_status, sshKeyPath);
540	    }
541	    process.exit(0);
542	  }
543	
544	  // No workspaceRoot and no result.json — treat as failure.
545	  writeResult(resultPath, {
546	    terminal_status: "failed",
547	    blocked_reason: "no_result_and_no_workspace_root",
548	    ...(tokenUsage ? { token_usage: tokenUsage } : {}),
549	  });
550	  process.exit(0);
551	}
552	
553	// ── Log flush (best-effort) ───────────────────────────────────────────────────
554	
555	function flushLog(
556	  workspaceRoot: string,
557	  featureId: string,
558	  taskId: string,
559	  taskBranch: string,
560	  runStartIso: string,
561	  gitAuthorEmail: string,
562	  gitAuthorName: string,
563	  stdout: string,
564	  outcome: string,
565	  sshKeyPath: string | undefined,
566	): void {
567	  try {
568	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
569	    mkdirSync(logsDir, { recursive: true });
570	
571	    const safeIso = runStartIso.replace(/[:.]/g, "-");
572	    const logFilename = `${safeIso}.jsonl`;
