/**
 * Unit tests for side-effects/open-pr.ts (openImplPr).
 *
 * No real GitHub API calls — spawnSync (used for curl) is mocked via vi.mock.
 *
 * Covers:
 *   1. Existing open PR on branch → reuse it (no POST)
 *   2. No existing PR → POST creates new one
 *   3. POST response lacks html_url / number → throws
 *   4. PR title follows feat(<featureId>/<taskId>): <taskTitle> convention
 *   5. GET query includes head=owner:branch and state=open
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { spawnSync } from "node:child_process";
import { openImplPr } from "../src/side-effects/open-pr.js";

// ── Mock spawnSync (used by curlJson inside open-pr.ts) ───────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, spawnSync: vi.fn() };
});

afterEach(() => {
  vi.clearAllMocks();
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const TASK_REPO_URL = "git@github.com:myorg/my-impl-repo.git";
const TASK_BRANCH = "feature/my-feature-T1";
const BASE_BRANCH = "main";
const FEATURE_ID = "my-feature";
const TASK_ID = "T1";
const TASK_TITLE = "Add widget component";
const GITHUB_TOKEN = "ghp_test_token";

const EXISTING_PR_URL = "https://github.com/myorg/my-impl-repo/pull/7";
const EXISTING_PR_NUMBER = 7;
const NEW_PR_URL = "https://github.com/myorg/my-impl-repo/pull/42";
const NEW_PR_NUMBER = 42;

function mockSpawnResult(jsonBody: unknown): ReturnType<typeof spawnSync> {
  return {
    pid: 0,
    output: [],
    stdout: JSON.stringify(jsonBody),
    stderr: "",
    status: 0,
    signal: null,
    error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

const baseOpts = {
  taskRepoUrl: TASK_REPO_URL,
  taskBranch: TASK_BRANCH,
  baseBranch: BASE_BRANCH,
  featureId: FEATURE_ID,
  taskId: TASK_ID,
  taskTitle: TASK_TITLE,
  githubToken: GITHUB_TOKEN,
};

// ── 1. Existing PR → alreadyExisted: true ────────────────────────────────────

describe("openImplPr — existing open PR", () => {
  it("returns alreadyExisted: true and reuses the existing URL", async () => {
    vi.mocked(spawnSync).mockReturnValueOnce(
      mockSpawnResult([{ html_url: EXISTING_PR_URL, number: EXISTING_PR_NUMBER }]),
    );

    const result = await openImplPr(baseOpts);

    expect(result.prUrl).toBe(EXISTING_PR_URL);
    expect(result.prNumber).toBe(EXISTING_PR_NUMBER);
    expect(result.alreadyExisted).toBe(true);
  });

  it("does not call POST when an existing PR is found", async () => {
    vi.mocked(spawnSync).mockReturnValueOnce(
      mockSpawnResult([{ html_url: EXISTING_PR_URL, number: EXISTING_PR_NUMBER }]),
    );

    await openImplPr(baseOpts);

    // Only one spawnSync call (the GET) — no POST.
    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(1);
    const [, args] = vi.mocked(spawnSync).mock.calls[0];
    expect((args as string[]).includes("POST")).toBe(false);
  });
});

// ── 2. No existing PR → POST new one ─────────────────────────────────────────

describe("openImplPr — no existing PR", () => {
  it("calls POST and returns alreadyExisted: false with new PR details", async () => {
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockSpawnResult([]))                                   // GET: no existing
      .mockReturnValueOnce(mockSpawnResult({ html_url: NEW_PR_URL, number: NEW_PR_NUMBER })); // POST

    const result = await openImplPr(baseOpts);

    expect(result.prUrl).toBe(NEW_PR_URL);
    expect(result.prNumber).toBe(NEW_PR_NUMBER);
    expect(result.alreadyExisted).toBe(false);

    expect(vi.mocked(spawnSync)).toHaveBeenCalledTimes(2);
    const [, postArgs] = vi.mocked(spawnSync).mock.calls[1];
    expect((postArgs as string[]).includes("POST")).toBe(true);
  });
});

// ── 3. POST response missing html_url → throws ───────────────────────────────

describe("openImplPr — GitHub API error", () => {
  it("throws when POST response lacks html_url", async () => {
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockSpawnResult([]))
      .mockReturnValueOnce(mockSpawnResult({ message: "Unprocessable Entity" }));

    await expect(openImplPr(baseOpts)).rejects.toThrow(
      "GitHub API PR creation failed",
    );
  });

  it("throws when POST response lacks number", async () => {
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockSpawnResult([]))
      .mockReturnValueOnce(mockSpawnResult({ html_url: NEW_PR_URL }));

    await expect(openImplPr(baseOpts)).rejects.toThrow(
      "GitHub API PR creation failed",
    );
  });
});

// ── 4. PR title convention ────────────────────────────────────────────────────

describe("openImplPr — PR title format", () => {
  it("uses feat(<featureId>/<taskId>): <taskTitle> as PR title", async () => {
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockSpawnResult([]))
      .mockReturnValueOnce(mockSpawnResult({ html_url: NEW_PR_URL, number: NEW_PR_NUMBER }));

    await openImplPr(baseOpts);

    const [, postArgs] = vi.mocked(spawnSync).mock.calls[1];
    const argsArray = postArgs as string[];
    const bodyIndex = argsArray.indexOf("-d") + 1;
    const body = JSON.parse(argsArray[bodyIndex]) as { title: string; head: string; base: string };

    expect(body.title).toBe(`feat(${FEATURE_ID}/${TASK_ID}): ${TASK_TITLE}`);
    expect(body.head).toBe(TASK_BRANCH);
    expect(body.base).toBe(BASE_BRANCH);
  });
});

// ── 5. GET query parameters ───────────────────────────────────────────────────

describe("openImplPr — GET query params", () => {
  it("passes head=owner:branch and state=open in the GET URL", async () => {
    vi.mocked(spawnSync).mockReturnValueOnce(
      mockSpawnResult([{ html_url: EXISTING_PR_URL, number: EXISTING_PR_NUMBER }]),
    );

    await openImplPr(baseOpts);

    const [, getArgs] = vi.mocked(spawnSync).mock.calls[0];
    const argsArray = getArgs as string[];
    const url = argsArray[argsArray.length - 1];

    expect(url).toContain("state=open");
    expect(url).toContain(encodeURIComponent("myorg:" + TASK_BRANCH));
  });
});

