51	  const actual = await importOriginal<typeof import("node:child_process")>();
52	  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
53	});
54	
55	// ── Fixtures ──────────────────────────────────────────────────────────────────
56	
57	const FEATURE_ID = "seam-test-feature";
58	const TASK_ID = "T1";
59	const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
60	const TASK_TITLE = "Seam test task";
61	const GIT_AUTHOR_EMAIL = "agent@test.com";
62	const GITHUB_TOKEN = "ghp_test";
63	const TASK_REPO_URL = "git@github.com:myorg/impl-repo.git";
