84	    ...overrides,
85	  };
86	}
87	
88	// ── Temp directory helpers ────────────────────────────────────────────────────
89	
90	const tmpDirs: string[] = [];
91	
92	function makeWorkspaceWithTask(task: Task): string {
93	  const dir = mkdtempSync(join(tmpdir(), "seam-dispatch-unit-"));
94	  tmpDirs.push(dir);
95	  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
96	  mkdirSync(tasksDir, { recursive: true });
97	  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
98	  return dir;
99	}
