101	function readTask(wsRoot: string): Task {
102	  return parseYaml(
103	    readFileSync(
104	      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
105	      "utf-8",
106	    ),
107	  ) as Task;
108	}
109	
110	function mockGitSuccess(): ReturnType<typeof spawnSync> {
111	  return {
112	    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
113	  } as unknown as ReturnType<typeof spawnSync>;
114	}
115	
116	function mockCurlPrList(items: Array<{ html_url: string; number: number }>): ReturnType<typeof spawnSync> {
117	  return {
