1	/**
2	 * Token usage extraction from claude --output-format stream-json stdout.
3	 *
4	 * Extracted from the former run-claude.ts so it can be unit-tested
5	 * independently and reused by the executor entrypoint.
6	 */
7	
8	/**
9	 * Scan stdout lines for token usage across all formats:
10	 *
11	 * - stream-json assistant events:
12	 *     {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,...}}}
13	 *   These fire once per turn; we sum all turns for the total.
14	 *
15	 * - Legacy flat usage object (plain-text / json format):
16	 *     {"usage":{"input_tokens":N,"output_tokens":N}}
17	 *
18	 * Returns accumulated {input, output} tokens, or undefined if no usage lines
19	 * are found in stdout.
20	 */
21	export function extractTokenUsage(
22	  stdout: string,
23	): { input: number; output: number } | undefined {
24	  let input = 0;
25	  let output = 0;
26	  let found = false;
27	
28	  for (const line of stdout.split("\n")) {
29	    const trimmed = line.trim();
30	    if (!trimmed.startsWith("{")) continue;
31	    try {
32	      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
33	
34	      // stream-json: assistant event carries per-turn usage inside message.
35	      if (parsed.type === "assistant") {
36	        const msg = parsed.message as Record<string, unknown> | undefined;
37	        const usage = msg?.usage as Record<string, unknown> | undefined;
38	        if (
39	          typeof usage?.input_tokens === "number" &&
40	          typeof usage?.output_tokens === "number"
41	        ) {
42	          input += usage.input_tokens as number;
43	          output += usage.output_tokens as number;
44	          found = true;
45	        }
46	        continue;
47	      }
48	
49	      // Legacy flat shape.
50	      const usage = parsed.usage as Record<string, unknown> | undefined;
51	      if (
52	        typeof usage?.input_tokens === "number" &&
53	        typeof usage?.output_tokens === "number"
54	      ) {
55	        input += usage.input_tokens as number;
56	        output += usage.output_tokens as number;
57	        found = true;
58	      }
59	    } catch {
60	      // Not a JSON line — skip.
61	    }
62	  }
63	
64	  return found ? { input, output } : undefined;
65	}
66

