/**
 * PR URL extraction from claude --output-format stream-json stdout.
 *
 * The pr-create skill emits the opened PR URL somewhere in Claude's output.
 * This module scans all output lines for a GitHub PR URL pattern.
 */

const GITHUB_PR_URL_RE = /https:\/\/github\.com\/[^/\s]+\/[^/\s]+\/pull\/\d+/;

/**
 * Scan Claude's stdout for a GitHub pull-request URL emitted by the
 * pr-create skill. Returns the first match found, or undefined if no PR
 * URL appears in the output.
 *
 * Handles both plain-text lines and JSON-encoded stream-json events — the
 * regex matches the URL regardless of whether it is bare or inside a JSON
 * string value.
 */
export function extractPrUrl(stdout: string): string | undefined {
  for (const line of stdout.split("\n")) {
    const match = GITHUB_PR_URL_RE.exec(line);
    if (match) {
      return match[0];
    }
  }
  return undefined;
}

